package servicio;
import java.sql.*;import java.util.*;import config.ConexionBD;
public class RankingDeportivoService {
 public List<Categoria> categorias(){String q="SELECT id,nombre,color_hex FROM categorias_deportivas WHERE activo=TRUE ORDER BY nivel_orden";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){List<Categoria>x=new ArrayList<>();while(r.next())x.add(new Categoria(r.getLong(1),r.getString(2),r.getString(3)));return x;}catch(SQLException e){throw new RuntimeException("No se pudieron cargar las categorias del ranking.",e);}}
 public List<Posicion> calcular(long categoriaId){if(categoriaId<=0)throw new IllegalArgumentException("La categoria es obligatoria.");String q="SELECT h.perfil_jugador_id,MAX(h.nombre_perfil_snapshot) jugador,COUNT(DISTINCT h.partido_id) pj,SUM(h.resultado='GANADOR') pg,"+
 "SUM(CASE WHEN h.resultado='GANADOR' THEN 4 ELSE 1 END + CASE tp.fase WHEN 'FINAL' THEN IF(h.resultado='GANADOR',8,4) WHEN 'SEMIFINAL' THEN IF(h.resultado='GANADOR',4,2) WHEN 'CUARTOS' THEN IF(h.resultado='GANADOR',2,1) ELSE 0 END) puntos,"+
 "SUM(CASE WHEN h.lado=1 THEN (SELECT COALESCE(SUM((s.puntos_pareja_1>s.puntos_pareja_2)-(s.puntos_pareja_1<s.puntos_pareja_2)),0) FROM torneo_partido_sets s WHERE s.partido_id=h.partido_id) ELSE (SELECT COALESCE(SUM((s.puntos_pareja_2>s.puntos_pareja_1)-(s.puntos_pareja_2<s.puntos_pareja_1)),0) FROM torneo_partido_sets s WHERE s.partido_id=h.partido_id) END) dif_sets,"+
 "SUM(CASE WHEN h.lado=1 THEN (SELECT COALESCE(SUM(s.puntos_pareja_1-s.puntos_pareja_2),0) FROM torneo_partido_sets s WHERE s.partido_id=h.partido_id) ELSE (SELECT COALESCE(SUM(s.puntos_pareja_2-s.puntos_pareja_1),0) FROM torneo_partido_sets s WHERE s.partido_id=h.partido_id) END) dif_games "+
 "FROM historial_competitivo_perfiles h JOIN torneo_partidos tp ON tp.id=h.partido_id WHERE h.categoria_deportiva_id=? GROUP BY h.perfil_jugador_id ORDER BY puntos DESC,pg DESC,(pg/COUNT(DISTINCT h.partido_id)) DESC,dif_sets DESC,dif_games DESC,jugador";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,categoriaId);try(ResultSet r=s.executeQuery()){List<Posicion>x=new ArrayList<>();int p=1;while(r.next()){int pj=r.getInt("pj"),pg=r.getInt("pg");x.add(new Posicion(p++,r.getLong(1),r.getString("jugador"),r.getInt("puntos"),pj,pg,pj-pg,pj==0?0:(int)Math.round(pg*100.0/pj),r.getInt("dif_sets"),r.getInt("dif_games")));}return x;}}catch(SQLException e){throw new RuntimeException("No se pudo calcular el ranking.",e);}}
 public List<Aporte> auditar(long perfilId,long categoriaId){String q="SELECT h.partido_id,t.nombre,tc.nombre,tp.fase,h.resultado,h.fecha_resultado,CASE WHEN h.resultado='GANADOR' THEN 4 ELSE 1 END base,CASE tp.fase WHEN 'FINAL' THEN IF(h.resultado='GANADOR',8,4) WHEN 'SEMIFINAL' THEN IF(h.resultado='GANADOR',4,2) WHEN 'CUARTOS' THEN IF(h.resultado='GANADOR',2,1) ELSE 0 END bonus FROM historial_competitivo_perfiles h JOIN torneo_partidos tp ON tp.id=h.partido_id JOIN torneo_categorias tc ON tc.id=h.torneo_categoria_id JOIN torneos t ON t.id=tc.torneo_id WHERE h.perfil_jugador_id=? AND h.categoria_deportiva_id=? ORDER BY h.fecha_resultado DESC";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,perfilId);s.setLong(2,categoriaId);try(ResultSet r=s.executeQuery()){List<Aporte>x=new ArrayList<>();while(r.next()){int b=r.getInt("base"),o=r.getInt("bonus");x.add(new Aporte(r.getLong(1),r.getString(2),r.getString(3),r.getString(4).replace('_',' '),r.getString(5),b,o,b+o,r.getTimestamp(6).toLocalDateTime()));}return x;}}catch(SQLException e){throw new RuntimeException("No se pudo auditar el ranking.",e);}}
 public record Categoria(long id,String nombre,String color) {public String toString(){return nombre;}}
 public record Posicion(int posicion,long perfilId,String jugador,int puntos,int partidos,int victorias,int derrotas,int efectividad,int diferenciaSets,int diferenciaGames){}
 public record Aporte(long partidoId,String torneo,String categoria,String fase,String resultado,int base,int bonus,int total,java.time.LocalDateTime fecha){}
}
